import { ok, fail } from './result.js';
import { getCustomer, TIER_DISCOUNTS, normalizeId } from './customers.js';
import { getProduct } from './catalogue.js';
import { nextInvoiceNumber } from './numbering.js';
import { roundCents } from './money.js';
import { isValidDate as validateDate, addDays } from './dates.js';

/**
 * Create a draft invoice for a customer with line items.
 * @param {{ customerId: string, issueDate: string, lines: Array<{ sku: string, qty: number, discountPercent?: number }>, terms?: string }} params
 * @returns {import('./result.js').ok<{ customerId: string, issueDate: string, status: string, lines: Array<{ sku: string, name: string, qty: number, unitPrice: number, vatRate: number, discountPercent: number }>, terms: string, dueDate: string }> | import('./result.js').fail}
 */
export function createInvoice({ customerId, issueDate, lines, terms }) {
  const normalizedCustomerId = normalizeId(customerId);
  const customerResult = getCustomer(normalizedCustomerId);
  if (!customerResult.ok) return customerResult;

  if (!validateDate(issueDate)) return fail('DATE_INVALID');

  const resolvedTerms = terms ?? 'NET30';
  const dueDate = calculateDueDate(issueDate, resolvedTerms);
  if (!dueDate) return fail('TERMS_INVALID');

  if (!Array.isArray(lines) || lines.length === 0) return fail('NO_LINES');

  const customer = customerResult.value;
  const tierDiscount = TIER_DISCOUNTS[customer.tier] ?? 0;

  const invoiceLines = [];
  for (const line of lines) {
    if (typeof line.qty !== 'number' || !Number.isInteger(line.qty) || line.qty <= 0) {
      return fail('QTY_INVALID');
    }

    if (line.discountPercent !== undefined && !isValidDiscount(line.discountPercent)) {
      return fail('DISCOUNT_INVALID');
    }
    const discountPercent = line.discountPercent !== undefined ? line.discountPercent : tierDiscount;

    const productResult = getProduct(line.sku);
    if (!productResult.ok) return productResult;

    const product = productResult.value;
    invoiceLines.push({
      sku: product.sku,
      name: product.name,
      qty: line.qty,
      unitPrice: product.unitPrice,
      vatRate: product.vatRate,
      discountPercent,
    });
  }

  return ok({
    customerId: normalizedCustomerId,
    issueDate,
    status: 'draft',
    lines: invoiceLines,
    terms: resolvedTerms,
    dueDate,
  });
}

/**
 * Add or increase a line on a draft invoice.
 * @param {{ status: string, lines: Array<{ sku: string, name: string, qty: number, unitPrice: number, vatRate: number, discountPercent: number }> }} invoice
 * @param {{ sku: string, qty: number, discountPercent?: number }} params
 * @returns {import('./result.js').ok | import('./result.js').fail}
 */
export function addLine(invoice, { sku, qty, discountPercent }) {
  if (invoice.status !== 'draft') return fail('NOT_DRAFT');

  if (typeof qty !== 'number' || !Number.isInteger(qty) || qty <= 0) {
    return fail('QTY_INVALID');
  }

  if (discountPercent !== undefined && !isValidDiscount(discountPercent)) {
    return fail('DISCOUNT_INVALID');
  }
  const discount = discountPercent ?? 0;

  const productResult = getProduct(sku);
  if (!productResult.ok) return productResult;

  const product = productResult.value;
  const newLines = invoice.lines.map((line) => ({ ...line }));
  const existingLineIndex = newLines.findIndex((line) => line.sku === sku);

  if (existingLineIndex !== -1) {
    newLines[existingLineIndex] = {
      ...newLines[existingLineIndex],
      qty: newLines[existingLineIndex].qty + qty,
    };
  } else {
    newLines.push({
      sku: product.sku,
      name: product.name,
      qty,
      unitPrice: product.unitPrice,
      vatRate: product.vatRate,
      discountPercent: discount,
    });
  }

  return ok({
    ...invoice,
    lines: newLines,
  });
}

/**
 * Remove a line from a draft invoice.
 * @param {{ status: string, lines: Array<{ sku: string }> }} invoice
 * @param {string} sku
 * @returns {import('./result.js').ok | import('./result.js').fail}
 */
export function removeLine(invoice, sku) {
  if (invoice.status !== 'draft') return fail('NOT_DRAFT');

  const lineIndex = invoice.lines.findIndex((line) => line.sku === sku);
  if (lineIndex === -1) return fail('LINE_NOT_FOUND');

  if (invoice.lines.length === 1) return fail('NO_LINES');

  const newLines = invoice.lines.filter((line) => line.sku !== sku);

  return ok({
    ...invoice,
    lines: newLines,
  });
}

/**
 * Apply a voucher to a draft invoice.
 * @param {{ status: string, voucher?: { code: string, amount: number } }} invoice
 * @param {{ code: string, amount: number }} voucher
 * @returns {import('./result.js').ok | import('./result.js').fail}
 */
export function applyVoucher(invoice, { code, amount }) {
  if (invoice.status !== 'draft') return fail('NOT_DRAFT');

  if (invoice.voucher) return fail('VOUCHER_EXISTS');

  if (typeof amount !== 'number' || !Number.isInteger(amount) || amount <= 0) {
    return fail('AMOUNT_INVALID');
  }

  return ok({
    ...invoice,
    voucher: { code, amount },
  });
}

/**
 * Issue a draft invoice, assigning it a number and changing its status to 'issued'.
 * @param {{ status: string, issueDate: string }} invoice
 * @param {string[]} existingNumbers - array of invoice numbers already used
 * @returns {import('./result.js').ok | import('./result.js').fail}
 */
export function issueInvoice(invoice, existingNumbers) {
  if (invoice.status !== 'draft') return fail('NOT_DRAFT');

  const number = nextInvoiceNumber(existingNumbers, invoice.issueDate);

  return ok({
    ...invoice,
    number,
    status: 'issued',
  });
}

/**
 * Calculate the total for a single line item (qty × unitPrice).
 * @param {{ qty: number, unitPrice: number }} line
 * @returns {number}
 */
export function lineTotal(line) {
  return line.qty * line.unitPrice;
}

/**
 * Calculate the discount for a single line item (lineTotal × discountPercent / 100).
 * @param {{ qty: number, unitPrice: number, discountPercent: number }} line
 * @returns {number}
 */
export function lineDiscount(line) {
  const total = lineTotal(line);
  const discount = total * (line.discountPercent ?? 0) / 100;
  return Math.max(0, discount);
}

/**
 * Calculate VAT for a single line item, based on the amount after discount.
 * VAT = (lineTotal - lineDiscount) × vatRate / 100, rounded per line.
 * @param {{ qty: number, unitPrice: number, discountPercent?: number, vatRate: number }} line
 * @returns {number}
 */
export function lineVat(line) {
  const total = lineTotal(line);
  const discount = lineDiscount(line);
  const baseAmount = total - discount;
  const vat = baseAmount * (line.vatRate ?? 0) / 100;
  return Math.max(0, roundCents(vat));
}

/**
 * Calculate totals for an invoice.
 * @param {{ lines: Array<{ qty: number, unitPrice: number, discountPercent?: number, vatRate: number }>, voucher?: { code: string, amount: number } }} invoice
 * @returns {{ subtotal: number, discount: number, vat: number, voucher: number, total: number }}
 */
export function invoiceTotals(invoice) {
  const subtotal = invoice.lines.reduce((sum, line) => sum + lineTotal(line), 0);
  const discount = invoice.lines.reduce((sum, line) => sum + lineDiscount(line), 0);
  const vat = invoice.lines.reduce((sum, line) => sum + lineVat(line), 0);
  const voucher = invoice.voucher?.amount ?? 0;
  const total = Math.max(0, subtotal - discount + vat - voucher);
  return { subtotal, discount, vat, voucher, total };
}

/**
 * Calculate the due date based on payment terms.
 * @param {string} issueDate - Date in YYYY-MM-DD format
 * @param {string} terms - 'NET14', 'NET30', or 'EOM'
 * @returns {string|null} - Due date in YYYY-MM-DD format, or null if terms are invalid
 */
function calculateDueDate(issueDate, terms) {
  switch (terms) {
    case 'NET14':
      return addDays(issueDate, 14);
    case 'NET30':
      return addDays(issueDate, 30);
    case 'EOM':
      return getLastDayOfMonth(issueDate);
    default:
      return null;
  }
}

/**
 * Get the last day of the month for a given date.
 * @param {string} date - Date in YYYY-MM-DD format
 * @returns {string} - Last day of the month in YYYY-MM-DD format
 */
function getLastDayOfMonth(date) {
  const d = new Date(date + 'T00:00:00Z');
  const year = d.getUTCFullYear();
  const month = d.getUTCMonth();
  const lastDay = new Date(Date.UTC(year, month + 1, 0)).getUTCDate();
  const monthStr = String(month + 1).padStart(2, '0');
  const dayStr = String(lastDay).padStart(2, '0');
  return `${year}-${monthStr}-${dayStr}`;
}

/**
 * Check if a discount percent is valid (a number from 0 to 100).
 * @param {unknown} discountPercent
 * @returns {boolean}
 */
function isValidDiscount(discountPercent) {
  return typeof discountPercent === 'number' && discountPercent >= 0 && discountPercent <= 100;
}

